package com.wanyuecity.energy.notification.provider;
import com.fasterxml.jackson.databind.*;import okhttp3.*;import org.springframework.stereotype.Component;import java.time.Duration;import java.util.Map;
@Component public class DingTalkWebhookProvider implements NotificationProvider {private final OkHttpClient http=new OkHttpClient.Builder().connectTimeout(Duration.ofSeconds(5)).readTimeout(Duration.ofSeconds(10)).writeTimeout(Duration.ofSeconds(10)).build();private final ObjectMapper json;public DingTalkWebhookProvider(ObjectMapper json){this.json=json;}public String provider(){return "DINGTALK";}public SendResult send(String url,NotificationMessage msg){try{String body=json.writeValueAsString(Map.of("msgtype","markdown","markdown",Map.of("title","现场设备核验任务","text",msg.content())));Request req=new Request.Builder().url(url).post(RequestBody.create(body,MediaType.get("application/json; charset=utf-8"))).build();try(Response r=http.newCall(req).execute()){String text=r.body()==null?"":r.body().string();boolean ok=r.isSuccessful()&&json.readTree(text).path("errcode").asInt(-1)==0;return new SendResult(ok,r.code(),limit(text,2000),ok?null:"provider rejected request");}}catch(Exception e){return new SendResult(false,null,null,e.getClass().getSimpleName()+": "+limit(e.getMessage(),300));}}private String limit(String s,int n){if(s==null)return null;return s.length()<=n?s:s.substring(0,n);}}
